from pathlib import Path
import runpy,json,stat
p=Path('/tmp/fc-round28-evidence');repo=Path('/workspace/共享/Eliora/未来教室计划');m=runpy.run_path(str(repo/'scripts/windows-probe.py'));key=Path('/config/.local/share/future-classroom-test-access/win11-192.168.10.212');r=m['Remote']('elior@192.168.10.212',key)
base=json.loads((p/'windows-before.json').read_text())
script=r'''$dirs=@(Get-ChildItem -LiteralPath $env:TEMP -Directory -ErrorAction Stop | Where-Object{$_.Name -match '^FutureClassroom-(RustProbe-|Test-)'}|Select-Object -ExpandProperty Name);$processes=@(Get-CimInstance Win32_Process |Where-Object{($_.ExecutablePath -and $_.ExecutablePath -match 'FutureClassroom-(RustProbe-|Test-)') -or ($_.Name -like 'fc-bootstrap*') }|ForEach-Object{@{name=$_.Name;pid=$_.ProcessId}});$tasks=@(Get-ScheduledTask |Where-Object{$_.TaskName -like 'FutureClassroom-RustProbe-*'}|Select-Object -ExpandProperty TaskName);$os=Get-CimInstance Win32_OperatingSystem;@{sshd=(Get-Service sshd).Status.ToString();build=$os.BuildNumber;os=$os.Caption;sshPublicAuthorizationSha256=(Get-FileHash -LiteralPath "$env:ProgramData\ssh\administrators_authorized_keys" -Algorithm SHA256).Hash.ToLowerInvariant();scratchDirectories=$dirs;ownedProcesses=$processes;ownedTasks=$tasks}|ConvertTo-Json -Depth 5 -Compress'''
report=json.loads(r.powershell(script));report['projectRunReadOnlySnapshot']=json.loads(r.powershell(m['project_run_snapshot_script']()));report['persistentKeyMode']=oct(stat.S_IMODE(key.stat().st_mode));report['authentication']='PASS'
report['publicAuthorizationUnchanged']=report['sshPublicAuthorizationSha256']==base['sshPublicAuthorizationSha256'];report['projectRunUnchanged']=report['projectRunReadOnlySnapshot']==base['projectRunReadOnlySnapshot']
assert report['sshd']=='Running' and report['publicAuthorizationUnchanged'] and report['projectRunUnchanged'] and report['persistentKeyMode']=='0o600'
assert not report['scratchDirectories'] and not report['ownedProcesses'] and not report['ownedTasks']
report['status']='PASS';(p/'windows-after.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':'PASS','sshd':report['sshd'],'authorizationUnchanged':True,'projectRunUnchanged':True,'scratchDirectories':0,'tasks':0,'processes':0}))
